// Drop jobs already analyzed in earlier runs (ids are recorded after analysis, below),
// then cap how many we analyze per run. Capping after the seen filter means skipped jobs get their turn on later runs.
const MAX_ANALYZE = 15;
const seen = $getWorkflowStaticData('global').seen || {};
return $input.all().filter((i) => i.json.job_id && !seen[i.json.job_id]).slice(0, MAX_ANALYZE);

const MIN_SCORE = 40;      // only notify at or above this score
const MAX_PER_RUN = 5;     // send at most this many per run, best score first
const KEEP_DAYS = 60;      // forget seen ids after this long

const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const now = Date.now();
for (const id of Object.keys(store.seen)) {
  if (now - store.seen[id] > KEEP_DAYS * 864e5) delete store.seen[id];
}

const jobs = Object.fromEntries($('Skip seen').all().map((i) => [i.json.job_id, i.json]));
const qualified = [];
for (const { json: a } of $input.all()) {
  const job = jobs[a.job_id];
  // A failed /analyze has no score: leave it unseen so tomorrow's run retries it.
  if (!job || typeof a.score !== 'number') continue;
  if (a.too_senior || a.score < MIN_SCORE) { // too_senior: job asks for more experience than we allow
    store.seen[a.job_id] = now;
    continue;
  }

  const lines = [
    `**${job.title}** at ${job.company} - score ${a.score} (semantic ${a.semantic_score}, keyword ${a.keyword_score})`,
    `${job.location} | via ${job.source}`,
    `<${job.url}>`, // angle brackets stop Discord from adding a link preview
    `Matched: ${a.matched_skills.join(', ') || '-'}`,
    `Gaps: ${a.gaps.join(', ') || '-'}`,
    a.summary,
  ];
  if (a.min_years_experience) lines.push(`Experience asked: ${a.min_years_experience} yr`);
  if (job.source === 'remotive') lines.push('Source: Remotive (remotive.com)');
  if (!a.skipped_email) lines.push('', `**${a.email_subject}**`, a.email_draft);
  qualified.push({ id: a.job_id, score: a.score, content: lines.join('\n').slice(0, 1900) }); // Discord caps messages at 2000 chars
}

qualified.sort((x, y) => y.score - x.score);
const sent = qualified.slice(0, MAX_PER_RUN);
// Qualified jobs cut by the cap stay unseen, so a later run can still send them.
for (const q of sent) store.seen[q.id] = now;
return sent.map((q) => ({ json: { content: q.content } }));
